// Quantos dias antes do vencimento o alerta deve avisar
const DIAS_ALERTA = 3;

// "Hoje" à meia-noite, para comparar só datas (sem horas)
const hoje = new Date();
hoje.setHours(0, 0, 0, 0);

// Um registro por produto: se o mesmo item veio em compras diferentes,
// fica o que vence primeiro
const porItem = {};

for (const linha of $input.all()) {
  const d = linha.json;

  // Item sem validade estimada: não dá para calcular, pula
  if (d.validade_estimada_dias === null || d.validade_estimada_dias === undefined) continue;

  // Data da compra = quando a linha foi gravada
  const compra = new Date(d.createdAt);
  compra.setHours(0, 0, 0, 0);

  // Vencimento = compra + dias de validade
  const vence = new Date(compra);
  vence.setDate(vence.getDate() + Number(d.validade_estimada_dias));

  // Diferença em dias (86.400.000 ms = 1 dia)
  const diasRestantes = Math.round((vence - hoje) / 86400000);

  // Fica só com o que vence de hoje até DIAS_ALERTA
  if (diasRestantes < 0 || diasRestantes > DIAS_ALERTA) continue;

  const chave = String(d.item).trim().toLowerCase();
  if (!porItem[chave] || diasRestantes < porItem[chave].dias_restantes) {
    porItem[chave] = {
      item: d.item,
      quantidade: d.quantidade,
      dias_restantes: diasRestantes,
      vence_em: vence.toLocaleDateString('pt-BR'),
    };
  }
}

// Ordena: o que vence primeiro vem primeiro
const resultado = Object.values(porItem)
  .sort((a, b) => a.dias_restantes - b.dias_restantes)
  .map(x => ({ json: x }));

return resultado;
